package com.bitedash.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="orders") public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @Column(name="delivery_address",nullable=false) private String deliveryAddress; @Column(name="total_amount",nullable=false,precision=10,scale=2) private BigDecimal totalAmount; @Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status=OrderStatus.PLACED; @Column(name="ordered_at") private LocalDateTime orderedAt=LocalDateTime.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) private List<OrderItem> items=new ArrayList<>(); protected Order(){} public Order(User u,String a,BigDecimal t){user=u;deliveryAddress=a;totalAmount=t;} public Long getId(){return id;} public User getUser(){return user;} public String getDeliveryAddress(){return deliveryAddress;} public BigDecimal getTotalAmount(){return totalAmount;} public OrderStatus getStatus(){return status;} public LocalDateTime getOrderedAt(){return orderedAt;} public List<OrderItem> getItems(){return items;} public void cancel(){status=OrderStatus.CANCELLED;} public void addItem(OrderItem i){items.add(i);}
}
